globalThis.ANDE_CHUNKS["a58518c5307692208053567fa55cdfa9ac204ef38040e0f2d4a91712fdfa6620"] = [{"id":"alibaba:199903180079","sourceKey":"alibaba","company":"阿里巴巴","title":"阿里巴巴研究型实习生-多模态大模型安全评测及原生安全增强","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903180079?deptCodes=","duty":"1. 参与多模态大模型（MLLM）及其应用场景的安全风险研究，探索文本、图像、视频、音频等跨模态交互中的新型攻击面（如跨模态语义鸿沟利用、隐写攻击），进行威胁建模与风险定级。\n2. 协助开展多模态安全攻防实验，包括视觉/语音越狱（Visual/Audio Jailbreak）、对抗样本生成（Adversarial Perturbation）、跨模态提示注入等，评测主流多模态模型在复杂输入下的鲁棒性与防御边界。\n3. 研究多模态大模型的原生安全增强技术，探索基于潜在空间防御（Latent Space Defense）的改进算法，从模型底层提升安全性。\n4. 跟踪前沿研究进展，调研多模态学习、对抗机器学习、模型对齐与可信AI领域的顶级会议论文（如CVPR, NeurIPS, ICLR等）及技术方案，为团队提供前沿技术洞察。\n5. 协助构建多模态安全评测基准与自动化工具链，沉淀高质量的跨模态攻击","requirements":"1、学历背景：计算机科学、人工智能、网络安全等相关专业，硕士或博士在读。\n2、算法基础：熟悉 Transformer 结构，深入理解主流多模态大模型架构（如 LLaVA, GPT-4V, Gemini, Stable Diffusion 等）及其训练/推理机制。\n3、攻防经验：了解对抗攻击（Adversarial Attacks）经典算法（如 PGD, FGSM），或有大模型越狱（Jailbreak）、Prompt Engineering 相关研究经验者优先。\n4、编程能力：熟练掌握 Python 及 PyTorch/TensorFlow 框架，具备良好的代码实现能力，能快速复现 Paper 中的算法。\n5、学术能力：在 AI 安全、CV、NLP 等领域的顶级会议（CVPR, ICCV, ACL, NeurIPS, CCS, USENIX Security 等）发表过论文者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903340001","sourceKey":"alibaba","company":"阿里巴巴","title":"阿里巴巴研究型实习生-智能体及应用安全评测研究","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903340001?deptCodes=","duty":"1.参与智能体（AI Agent）及其应用场景的安全风险研究，探索智能体在复杂交互环境中的攻击面、威胁建模与防御机制。\n2.协助开展大模型安全攻防实验，包括越狱攻击、提示注入、对抗样本构造等，评测不同智能体架构在任务执行中的鲁棒性与防御能力。\n3.研究智能体决策过程中的风险建模方法（如基于马尔可夫决策过程的行为建模），并设计相应的安全护栏与防御算法。\n4.跟踪前沿研究进展，调研智能体安全、可信 AI 与大模型内容安全相关的学术论文与技术方案，为团队提供前沿洞察。\n5.协助构建安全评测基准与工具链，形成可复现的安全评测流程，支持团队在多任务、多场景下的风险分析与能力验证。","requirements":"1.计算机科学、人工智能、网络安全、数学等相关专业在读博士，具备AI安全、强化学习或大模型相关研究背景。\n2.熟悉大语言模型（如GPT、LLaMA、Qwen 等）的基本原理，熟悉深度学习框架（如PyTorch、TensorFlow）。\n3.对AI安全攻防有浓厚兴趣，熟悉常见攻击方式（提示注入、对抗样本、数据投毒等）或防御技术（鲁棒优化、内容安全检测、代理模型防御等）。\n4.具备良好的研究能力和论文阅读能力，精通Python/C++/Java中至少一门语言，具备扎实的数据结构、算法基础及工程化能力，能够快速理解前沿工作并复现相关实验。\n5.具备良好的团队协作意识与沟通能力，能够在导师指导下推进课题研究。\n6.在 AI 安全、智能体或机器学习相关领域有论文发表（如ACL、CCS、NeurIPS、ICLR等）、竞赛获奖或开源项目经验者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903340002","sourceKey":"alibaba","company":"阿里巴巴","title":"阿里巴巴日常实习生-大模型伦理评测","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903340002?deptCodes=","duty":"1. 针对模型合规及伦理风险，包括特殊群体保护、AI意识与过拟人化、危机干预等，结合自身科研研究，明确风险定义，平衡模型安全性和有用性。\n2. 建设伦理风险相关知识库与风险画像体系，沉淀人类弱势群体画像、敏感场景分类、AI影响人类认知/情绪/决策/行为的风险类型与表现、风险触发机制、干预策略及案例库，为评测、红队、模型对齐和产品治理提供系统化知识支撑。\n3. 构建科学、全面的伦理评测集。设计并落地覆盖多维度风险场景的伦理评测基准（Benchmark），融合黑盒评测与白盒神经元分析，深入解析模型“为何如此回答”，实现从“发现问题”到“理解根源”的跃迁。\n4. 负责A2A评测实验环境搭建及实验实施，将传统纯LLM评测拓展至Agent、多智能体交互、工具调用、端到端任务链路等复杂场景，设计可复现的实验流程、观测指标与风险判定标准，评估模型在真实任务环境中的伦理安全性、稳定性和行为边界。","requirements":"1. 硕士及以上学历，人工智能、计算机科学、认知科学、哲学、社会学、心理学、法学等相关专业背景；\n2. 对AI伦理、AI安全、模型对齐（Alignment）有浓厚兴趣或研究经验，熟悉主流大模型风险类型，如歧视、滥用、意识幻觉、过拟人化、心理/行为影响等；\n3. 具备扎实的分析能力，能独立设计实验、构建评测集，并擅长从数据、案例和模型行为中提炼洞察；\n4. 熟悉LLM、Agent、多智能体交互、工具调用或端到端任务评测者优先；有A2A评测环境搭建、自动化评测平台、模型红队或安全评测经验者优先；\n5. 有伦理风险知识库、风险分类体系、用户/群体画像、行为影响分析、社会心理学或人机交互研究经验者优先；\n6. 具备出色的跨团队协作与组织能力，能推动专家网络协同，有学术或行业影响力者优先；\n7. 心怀敬畏，关注技术的社会影响，致力于构建可信赖、负责任的AI。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700003","sourceKey":"alibaba","company":"阿里巴巴","title":"品牌内容运营-海外市场","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700003?deptCodes=","duty":"1.洞察海外社交媒体热点、行业趋势及用户需求，参与Alibaba.com品牌内容的策划与制作；\n2.负责Instagram、Facebook、LinkedIn、YouTube等平台的图文及视频内容，提升内容质量、互动和品牌影响力；\n3.参与海外KOL/KOC的挖掘、沟通与合作运营，扩大品牌在目标市场的传播；\n4.围绕AI产品策划传播内容，帮助全球中小企业了解并使用AI，提升产品在B2B市场的认知和渗透；\n5.协同内部团队及代理商，参与海外整合营销项目的策划与落地。","requirements":"1.有审美，有创作优秀品牌作品的热忱，敢于创造和敢于尝试，也认真负责；\n2.每周到岗≥4天，实习期≥3个月；\n3.英语需要作为工作语言，熟练掌握法语、德语、意大利语或西班牙语者优先；\n4.有品牌营销、社交媒体、内容策划或视频制作经验者优先；\n5.关注互联网和AI行业，愿意主动尝试AI工具，有相关使用经验者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700009","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生-视频生成模型优化研究","city":"北京/杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700009?deptCodes=","duty":"岗位概述：\n聚焦文生视频模型的推理与训练加速技术，探索、设计并实现全新的算法与系统级解决方案。解决当前文生视频模型面临的最大瓶颈：高昂的计算成本与漫长的生成时间。\n\n岗位职责：\n1、前沿算法研究与创新：\n（1）深入研究当前主流文生视频模型（如Wanx、CogVideo等）的架构，定位其在计算、内存及I/O上的核心瓶颈；\n（2）探索并设计全新的高效模型架构，将MoE、Sparse Attention等先进思想引入Diffusion Transformer，研究少步/单步生成技术；\n（3）针对视频生成中的时序建模，研发更轻量级但同样有效的时空注意力机制。\n2、系统级优化与实现：\n（1）设计并实现高性能的自定义CUDA/Triton核函数，以支持不规则稀疏计算模式或新型算子；\n（2）利用量化、剪枝、蒸馏等模型压缩技术，在保持生成质量的同时，大幅缩减模型尺寸和计算量；\n（3）研究适用于高分辨率、长","requirements":"1、计算机科学、人工智能、电子工程或相关专业硕士及以上学历，博士优先；\n2、扎实的深度学习与计算机视觉基础，熟悉扩散模型、Transformer、生成式AI等核心技术；\n3、在文生图或文生视频领域有实际研究或项目经验，了解主流模型架构（如 Wanx、CogVideo等）；\n4、精通 PyTorch 框架，具备良好的代码工程能力；\n5、在 NeurIPS / ICML / CVPR / ICLR 等顶级会议发表过相关论文者优先；\n6、具备优秀的科研创新能力、问题抽象能力与跨团队协作精神。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700010","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生-多模态大模型软硬协同优化","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700010?deptCodes=","duty":"1、负责研究AI大模型的推理性能优化算法，优化大模型推理部署的算力和访存瓶颈，提升AI模型在GPU、AI加速器等硬件上部署性能效率，推动大模型普惠应用和高性价比的竞争力；\n2、负责高性能软硬结合的大模型推理优化方法研究，在AI类业务场景尤其是大模型场景下，通过结合模型算法和硬件来充分挖掘软硬件协同的组合优化潜力，带来高价值的性能和成本优势；\n3、负责研发业界SOTA的多模态大模型计算性能优化方法创新，增强技术壁垒，并在云的商业业务中产生核心价值。","requirements":"1、博士在读，且发表过一篇以上的AI类CCF-A会议的文章；\n2、熟悉AI深度学习和大模型原理和技术栈，有清晰的理解和认系统性的认知，熟悉AI部署和推理流程，hands-on操作过大模型的部署和性能分析，具备独立工程研发、性能分析和落地能力；\n3、熟悉常见的模型性能优化和推理加速方法，包含不限于量化/压缩/算子优化/结构优化/并行等，有对大模型优化加速的经验；\n4、学习和研究能力强，能够快速掌握新领域和新技术，并具备创新能力；思考沟通表达能力强。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700012","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生-大模型高效强化学习系统研究","city":"北京/杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700012?deptCodes=","duty":"我们正在寻找对大模型系统优化充满热情的优秀在读学生，参与大模型后训练阶段（Post-Training）关键系统与架构的前沿研究。你将深度参与千亿级大模型在强化学习训练、推理效率、训推分离架构、智能体（Agent）系统等方面的系统级优化工作，探索高MFU、低延迟、高吞吐的下一代AI基础设施。\n如果你热爱系统与AI的交叉领域，希望在真实超大规模场景中打磨技术，欢迎加入我们，与顶尖研究者和工程师共同推动大模型系统的技术边界！\n\n研究方向与实习内容：\n你将从以下四个核心方向中选择1-2个深入参与，开展系统性研究与工程实现：\n\n1. 后训练 MFU（Model FLOPs Utilization）优化\n研究SFT、RLHF、DPO等后训练任务中的计算效率瓶颈；\n设计高MFU的训练策略与系统支持，优化计算密度（如序列填充、混合批次、梯度累积等）；\n探索算力利用率提升路径，结合通信、显存、计算进行端到端","requirements":"1. 在读博士研究生，计算机相关专业；\n2.有大模型后训练或者强化学习相关经验和工作背景；\n3.有A类会议或者期刊论文发表经历；\n4.有较强的代码能力，熟练掌握Python编程。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700014","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - PolarDB in-DB AI协同加速推理","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700014?deptCodes=","duty":"1）构建数据库内AI推理系统架构，高效整合CPU，GPU等资源，设计数据迁移管理机制，优化模型（包括大模型和小模型）的核心性能指标；\n2）研发具备负载自适应能力的推理框架，开发高精度指标采集模块，实现基于实时负载特征的动态参数调优功能；\n3）研究在精度可接受范围内，多种近似推理及轻量化技术，包括采用模型压缩（如量化、剪枝）或近似算法（如近似最近邻搜索）降低计算开销。","requirements":"1.计算机相关方向博士，包括，计算机科学、人工智能、软件工程或相关专业；\n2.有相关领域顶会论文（包括但不限于SIGMOD,ICDE,VLDB,ICML,ICLR,AAAI,NeuralPS等）发表；\n3.熟练掌握Linux环境下的C++/Python/JAVA等1至2种以上语言，具备复杂系统的设计开发与调试能力；\n4.熟悉至少一种大模型推理或微调框架，包括但不限于：DeepSpeed、LLaMA-Factory、vLLM、SGLang等；\n5.有强烈的工作责任心，较好的学习能力、沟通能力和自驱力，能够快速的响应和行动；\n6.加分项：具有大型系统研发经验；或有大模型推理或微调相关的技术落地经验。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700015","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 云原生多租KV数据库的隔离与调度优化研究和应用","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700015?deptCodes=","duty":"Tair是基于云原生基础设施的KV数据库产品。在技术上期望通过云的规模化效应，基于云基础设施，面向海量的各种规模的客户提供更低的成本和更好的弹性。从工程实践和业务分析上看到对比当前主流的单租户架构模式，多租户的架构聚合度提升带来的成本优化能极大的提升云数据库的竞争力，但同时在租户影响上面对的挑战也比较大。\n\n基于以上背景，本项目期望聚焦如下技术问题的研究：\n1.优化KV存储引擎在复杂流量场景和多租户场景的延迟表现；\n2.KV存储引擎在多租户场景下的资源隔离、限流相关技术研究；\n3.研发多租的分布式KV集群如何在提升弹性的同时能更高效的利用资源。","requirements":"1. 计算机或相关方向博士、硕士在读。扎实的工程能力，优良的编程风格，熟悉C++/Java/Go/Python等1至2种语言；\n2. 熟悉数据库/存储系统和优化技术，例如存储引擎（LSM/B+树），分布式系统弹性调度等；\n3. 完成原型系统开发，相关技术经过验证，具有效果，具备合入产品的要求；同时具备清晰的设计文档，包括验证的方法、产品性能、业务落地可行性等报告；\n4. 发表CCF-A类或者领域内顶级会议、期刊论文，并申请相关专利。\n\n加分项：\n1.在数据库/存储/系统等顶会发表论文经验；\n2.代码能力突出，有ACM等竞赛获奖经历；\n3. 参与过数据库/存储系统的开源社区。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700016","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 基于多模态的核心数据链路研究","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700016?deptCodes=","duty":"我们正在寻找对人工智能、多模态数据处理、系统性能优化感兴趣的实习生，参与一个面向多模态数据获取、解析、压缩与高效传输的研究课题。该课题聚焦于提升多模态系统在复杂环境下的实时性表现与资源利用率，具有广泛的应用前景（如智能运维、RAG检索增强生成、边缘计算等）。你将参与的工作包括但不限于：\n1. 多模态数据采集与预处理：从网页、API、数据库、摄像头、麦克风等来源获取文本、图像、音频和视频数据；\n2. 多模态数据解析与特征提取：使用OCR、ASR、NLP、CV等技术解析不同模态内容；\n3. 模型轻量化与加速：探索基于Transformer、CNN、LSTM等模型的压缩、蒸馏、量化方法；\n4. 系统级优化与部署：设计低延迟、低资源占用的数据处理流程，支持在边缘设备上运行；\n5. 性能评估与实验分析：构建测试集，评估系统的吞吐量、响应时间、准确率等关键指标；\n6. 撰写技术文档与研究报告：整理实验","requirements":"1.计算机或相关方向博士、硕士在读；\n2.在数据库、人工智能、系统、安全等领域有顶会论文发表经验；\n3.有系统研发能力，并善于与团队交流合作；\n4.富有创造力，有面向落地场景解决实际问题的意愿。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700017","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 智能多模态向量索引架构研究","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700017?deptCodes=","duty":"1.研发融合结构化查询与向量检索的混合执行引擎；\n2.设计基于深度学习的索引参数自优化框架；\n3.开发分布式环境下的动态负载均衡算法；\n4.构建多维度查询性能评估指标体系。","requirements":"1.计算机科学博士/硕士在读，在数据库、人工智能、系统等领域有顶会论文发表经验优先；\n2.熟悉PostgreSQL/MySQL等数据库内核架构；\n3.掌握C++/Rust系统开发，有OLAP引擎开发经验者优先；\n4.具备机器学习基础，熟悉图神经网络或强化学习框架。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700018","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 基于安全容器应用内核实现多Pod高效协同通信机制","city":"杭州/上海","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700018?deptCodes=","duty":"专注于安全容器系统的AI基础设施的研究、探索和开发，具体职责包括：\n\n1. 探索阿里云安全容器系统和AI基础设施演进，支撑大规模AI业务；\n2. 使能安全容器系统运行下一代AI基础设施，打造业界领先大规模AI算力基础设施；\n3. 结合下一代AI基础设施、安全容器和AI业务协同优化，打造高性能、低成本的AI算力。","requirements":"1. 扎实的工程能力，深入理解CPU架构和linux kernel，具备复杂系统的设计开发调试能力；\n2. 优良的沟通表达能力、具备快速学习的能力，以及深入钻研技术问题的耐心\n3. 具备独立完成CCF-A类或者领域内顶级会议论文写作","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700019","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 基于RAG技术和知识图谱的光网络状态问答应用","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700019?deptCodes=","duty":"研究、探索将RAG技术和知识图谱技术结合的方式，并在此基础上开发光网络状态问答系统。具体职责包括：\n1、 探索通过LLM和RAG技术实现从用户自然语言到Gremlin图谱查询语句的推理，并基于人工或AI工具构建一定数量的测试用例，覆盖光网络实际规划、建设、运维等场景，用于评估推理过程的可靠性；\n2、 探索使用开源或阿里内部工具搭建基础RAG平台，串接用户提问、Gremlin查询语句生成、知识图谱查询、结果返回等子流程，实现一个基础的在线光网络状态查询服务；\n3、 针对复杂提问，探索使用多轮查询机制，在复杂查询场景下能够结合LLM的语义理解能力自主分解用户意图，自主编排查询路径，提升查询效率。","requirements":"1. 深入掌握RAG架构原理，熟悉Python语言和常用设计模式，具备某专业领域文本生成模型的开发和使用经验；\n2. 熟悉光网络的基本网络模型，对传输设备硬件有清晰的认识；\n3. 优良的沟通表达能力、团队合作意识和经验；具备快速学习的能力，以及深入钻研技术问题的耐心。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700020","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 大规模LLM模型训练优化研究项目","city":"北京/杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700020?deptCodes=","duty":"随着模型尺寸和数据规模的持续扩大，预训练任务已成为AI研究和发展中最为资源密集的环节之一。本项目旨在深入的理解预训练任务的workload特点，定位性能瓶颈，并进行优化从而降低预训练任务的成本开销。例如从Pipeline，显存，通信优化等方面优化MoE大规模训练任务的吞吐，支持包括通义实验室等领域方向。","requirements":"候选人应为计算机及相关专业的博士或硕士研究生，且对机器学习系统有充分的兴趣；最好有机器学习系统及分布式系统相关研究和开发经验，了解或熟悉Megatron/TransformerEngine等LLM训练相关系统；\n需要产出论文和专利等高水平的学术成果。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700021","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 多时间尺度的智能化数据库性能调优","city":"北京/杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700021?deptCodes=","duty":"发现数据库系统的性能瓶颈并作出针对性优化是一项重要工作。随着各类智能算法的发展和应用，学术界和业界也逐渐开始利用智能算法优化数据库系统中的各种模块，我们也考虑在实际产品中实现智能化数据库调优能力，项目内容包括但不局限于:\n1、数据库可观察性接口：云原生数据库系统含有多种资源，针对性能问题实现系统可观测接口，数据收集与清洗；\n2、数据库可操控性接口：定量化数据库系统对外提供的可操控接口特性；\n3、多时间尺度的数据库性能分析模型：需要将已有的系统可观察性和可操控性模型化、定量化，建立多时间尺度的系统状态评估模型和状态迁移模型；\n4、具有特征性的数据库性能调优算法：基于已有的可观、可控接口及数据库性能模型，设计并实现用于智能化自适应的数据库性能调优算法。","requirements":"1、针对PolarDB实现的原型系统及源码；\n2、相关技术方案申请专利；\n3、研究成果发表CCF-A类会议或期刊论文。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700025","sourceKey":"alibaba","company":"阿里巴巴","title":"虎鲸文娱-鲸英班-AI美术设计&视频制作（少儿动画方向）","city":"北京","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700025?deptCodes=","duty":"1、资产生成： 理解内容需求，根据美术设定使用AI生成3D美术资产图。\n2、视频生成： 理解导演的分镜需求，用AI生成成片视频。\n3、精修补位： 有手绘能力，在AI生成前可以提高生成的精准度，同时对AI生成的瑕疵素材进行手绘或数字化修复，实现“人机协作”的高精度产出。\n4、资产模型：辅助制片人一起建立覆盖资产、提示词和风格库，提升制作效率。","requirements":"1、美术专业，有传统动画美术经验和AI动画抽卡经验。\n2、扎实的绘画功底和3D造型能力。\n3、精通生成式AI模型，能通过AI实现高效率的美术迭代。\n4、对中国儿童动画的色彩搭配、角色亲和力有敏锐触觉。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700026","sourceKey":"alibaba","company":"阿里巴巴","title":"灵犀互娱-海外策划实习生（海外休闲）","city":"北京","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700026?deptCodes=","duty":"你将会负责：\n1、游戏功能设计、撰写策划案和数值计算等，并协调和推动项目进度；\n2、对行业优秀产品进行总结分析，推动游戏的系统功能优化，提升产品竞争力；\n3、与程序、美术密切协作，推动功能开发与实现，确保设计方案的落地与上线效果；\n4、休闲游戏的地图编辑、叙事关卡配置、更新和创意设计工作。","requirements":"我们期望你：\n1、本科及以上学历，专业不限，逻辑思维优秀，有一定的审美能力；\n2、每周能够到岗4天及以上，能够连续实习3个月及以上；\n3、热爱休闲游戏，对主流休闲游戏玩法比较了解，有休闲游戏行业发展意愿；\n4、具备良好的文档编写和沟通表达能力，能够清楚地传达设计思路；\n5、具备优秀的跨团队协作和推动能力，敢于提出想法并推动团队协作进程；\n6、加分项：对海外休闲游戏、海外用户、海外社交平台有认知和经历为佳。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903700027","sourceKey":"alibaba","company":"阿里巴巴","title":"日常实习生-算法技术-AI助手算法工程师","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903700027?deptCodes=","duty":"淘天集团AI助手算法团队承担了淘天集团新一代AI原生购物助手的开发工作，通过统一的All in One大模型解决淘宝在不同场景的用户需求。团队在大模型强化学习、Agentic训练、原生多模态训练以及Agent框架设计有着行业领先的认知和实际落地效果。\n在这里，你将\n● 全链路模型训练\n    ○ 深度参与购物场景统一大模型的完整训练周期：预训练退火 → SFT → RLVR → RLHF\n    ○ 你碰到的不是一个冻结的API，而是一个你可以从底层塑造的模型\n● Agent框架设计——让大模型真正\"能办事\"\n    ○ 设计大模型原生的Agent架构，通过Skill编排、Sub-agent协作等机制，将淘系搜索、推荐、交易、客服等全域能力注入AI助手\n    ○ 让模型不只是\"能聊\"，而是\"能买、能比、能帮你做决定\"\n●  奖励信号发现——在真实场景中定义\"什么是好\"\n    ○ 基于淘","requirements":"1. 计算机科学、人工智能、机器学习等相关领域的硕士或博士在校生。\n2. 具备较强的分析问题和解决问题的能力，逻辑思维清晰，拥有良好的自学能力。\n3. 参加ACM或同类型算法竞赛获奖者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903720007","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 大模型推理加速以及高效微调核心技术研究","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903720007?deptCodes=","duty":"职位描述：\n1.设计和实现面向大模型推理的多层级存储系统，综合利用多种硬件进行数据的存储和迁移管理，优化大模型缓存利用率，提升推理性能；\n2.设计负载感知的推理框架自调优能力，设计高效的指标采集模块，能够根据对不同负载自动调优推理框架的参数；\n3.优化模型量化以及模型卸载技术，进一步提升单机场景下支持的模型规模；\n4.设计高效微调框架，集成并优化微调算法，实现动态策略调度模块，基于任务特征挑选最合适的微调方案。","requirements":"1.计算机科学、人工智能、软件工程或相关专业在读博士，硕士；\n2.有相关领域顶会论文（包括但不限于ICML,ICLR,AAAI,NeuralPS,VLDB，SIGMOD等）发表经验；\n3.熟练掌握Linux环境下的C++/Go/Python/Shell等1至2种以上语言，具备复杂系统的设计开发与调试能力；\n4.熟悉至少一种大模型推理或微调框架，包括但不限于：DeepSpeed、LLaMA-Factory、vLLM、SGLang等；\n5.有强烈的工作责任心，较好的学习能力、沟通能力和自驱力，能够快速的响应和行动。\n\n加分项：\n1.理解GPU硬件架构，理解GPU软件栈（CUDA，cuDNN)，具备GPU性能分析的经验；\n2.有大模型推理或微调相关的技术落地经验，比如：KVCache相关优化的实现。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903720008","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 基于人工智能的数据库自动调优方案研究","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903720008?deptCodes=","duty":"数据库智能调优方案研发，具体职责包括：\n1.通过应用Agent、RAG等技术，开发大语言模型驱动的数据库智能调优工具，包括自动计划标注管理、表结构优化、自动构建物化视图等能力；\n2.设计基于历史SQL运行数据的LLM训练与调优方案，并建设持续在线学习能力；\n3.设计智能优化评估工具。","requirements":"1.计算机方向博士或硕士在读；\n2.具备复杂系统的开发能力，熟悉Python、C++与常用设计模式；\n3.熟悉LLM技术，包括训练、推理、Agent等；\n4.熟悉数据库内核原理，具备内核开发经验者优先；\n5.勇于探索前沿技术，并具备落地解决工程问题的激情。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903720010","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - JVM优化参数的泛化迁移应用","city":"上海","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903720010?deptCodes=","duty":"Java应用程序的运行时行为由静态的程序和动态的workload共同决定，即使相同的Java应用在不同的workload上工作时，也会表现出不同的运行时行为。通过对应用运行时相似度建模，可以快速将已训练出的JVM优化参数泛化迁移到新的应用中。\n\n我们需要您可以研究解决应用程序运行时相似度的问题，主要包括以下职责：\n1. 研究建立应用的参数泛化迁移相似度模型\n2. 在实际应用中验证相似度模型\n3. 用相似度模型加速JVM优化参数训练的过程","requirements":"1. 扎实的工程能力，优良的编程风格，熟悉Python/C++语言和常用设计模式，具备复杂系统的设计开发调试能力；\n2. 优良的沟通表达能力、团队合作意识和经验；具备快速学习的能力，以及深入钻研技术问题的耐心；\n3. 熟悉计算机体系结构基础知识，有扎实高性能计算(GPU/x86/ARM等)、或机器学习方面的经验；","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903720011","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 大模型训推场景超长序列并行的通信计算重叠","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903720011?deptCodes=","duty":"专注于大规模分布式文生视频/文生图推理系统的研究、探索和开发，具体职责包括：\n探索高性能、可扩展的分布式 DiT 推理引擎，支持大规模文生视频/文生图场景的高效部署；\n深入优化高性能算子、运行时、分布式策略等，打造业界领先的DiT推理引擎；\n分析现有引擎和典型负载的性能瓶颈，提出并实现创新的优化技术；\n针对文生视频/文生图等重点场景，构建业界领先的优化解决方案。","requirements":"扎实的工程能力，优良的编程风格，熟悉Python/C++语言和常用设计模式，具备复杂系统的设计、开发、调试能力；\n熟悉计算机体系结构基础知识，有扎实的高性能计算（GPU）、或推理框架、或模型算法优化（量化/稀疏等）方面的经验； \n熟悉分布式系统、并行计算、通信优化等相关技术，具备大规模系统性能调优经验。\n优良的沟通表达能力、团队合作意识和经验；具备快速学习的能力，以及深入钻研技术问题的耐心；\n\n加分项\n有突出的学术背景和创新研究能力；\n对DiT、文生视频/文生图等重点场景的系统优化或前沿算法有深入务实的经验；\n具有GPU高性能Kernel开发和优化经验；\n熟悉序列并行、数据并行等分布式训练/推理策略，具备通信开销评估与建模经验；\n有计算与通信重叠技术、动态策略优化等相关实践经验。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903720013","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 资源三层解耦形态下的云原生数据库研究","city":"北京/杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903720013?deptCodes=","duty":"基于存储和计算分离的第一代云原生数据库，其CPU和内存资源依然强绑定，导致计算和内存资源不能实现按量付费。因此，本团队对三层解耦技术进行了探索和实现，完全分离数据库内的CPU，内存，存储资源，并构成三个独立的资源池，用户可弹性扩展任何一种资源，且只需为其动态消耗的资源买单。基于以上背景，本项目聚焦但不局限于以下关键问题的研究：\n1、基于三层解耦形态的分布式事务机制。在资源三层解耦部署形态下，已有的分布式事务机制不再适用，需研究适用于三层解耦部署形态的高效分布式事务机制；\n2、基于三层解耦形态的死锁检测机制。对于并发执行的事务，如何结合三层解耦技术来避免死锁的发生，以及如何尽早检测到死锁并打破死锁，以减少事务执行的等待时间；\n3、探索结合机器学习的资源弹性扩缩容机制。如何结合机器学习的方法来对用户业务流量进行预测，并在数据库集群维度对资源进行调度和分配，在满足用户业务对数据库性能需求的同时，","requirements":"1、实现的原型系统及源码；\n2、相关技术方案申请专利；\n3、研究成果发表CCF-A类会议或期刊论文。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903720020","sourceKey":"alibaba","company":"阿里巴巴","title":"日常实习生-业务技术-AI研发算法实习生","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903720020?deptCodes=","duty":"我们正在面向淘宝复杂工程技术体系，构建深度理解研发上下文的垂域大模型，打造具备\"架构师级\"洞察力的研发智能体。作为实习生，你将参与以下方向的研究与实践：\n\n1. 领域模型训练： 参与研发垂域大模型的数据构建与训练工作，包括研发数据的高质量组织与清洗、用户轨迹数据的迭代优化，以及持续预训练（CPT）、指令微调（SFT）、强化学习对齐（RL/RLHF）等训练流程。\n2. 理解与记忆能力研究： 参与探索如何让模型更好地理解、记忆和运用领域知识，提升模型在实际研发场景中的专业能力。\n3. 能力评估与迭代： 参与评测体系建设，协助评估模型在研发场景中的实际表现，分析bad case，推动数据和算法的持续优化。","requirements":"岗位要求：\n1. 计算机科学、人工智能、软件工程等相关专业，毕业时间在26年11月以后的硕博在校生。\n2. 具备扎实的NLP基础，有LLM大模型相关的研究或项目经验，熟悉预训练、SFT、RLHF等关键技术。\n3. 熟悉Python，熟练掌握PyTorch等深度学习框架。\n4. 具备良好的问题拆解和解决能力，强自驱力与团队协作精神，敢于探索新思路、新技术。\n\n加分项：\n1. 在相关领域顶会（如NeurIPS、ICML、ICLR、ACL、EMNLP、AAAI等）发表过一作论文。\n2. 理解软件研发全流程，有将AI技术应用于软件工程的经验，或具备知识图谱、知识工程背景。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903720029","sourceKey":"alibaba","company":"阿里巴巴","title":"灵犀互娱-游戏交互实习生","city":"广州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903720029?deptCodes=","duty":"1. 支持 UX 和UI 设计师在游戏系统玩法上创造更舒适的用户体验；\n2. 应用基本的用户体验设计原则，确保玩家从我们的游戏中获得清晰有效的信息反馈；\n3. 与游戏设计师合作完善用户旅程，然后制作线框和原型以简化升级整体心流体验；\n4. 进行用户研究和竞品分析，以更好地了解我们的产品和用户；\n【我们的支持】你可以向我们团队的高级用户体验设计师学习，了解良好用户体验的要素并实践落地，点亮你的天赋！","requirements":"1. 了解并能应用核心用户体验设计原则（格式塔原则、启发式方法等）‘\n2. 精通原型设计工具（Adobe XD、Axure、Figma 等），可帮助你设计和迭代不同保真度的线框图；\n3. 具备好奇心和批判性思维来评估所进行的用户测试和研究；\n4. 具备玩家视角，能理解玩家的诉求；\n5. 热爱游戏，并理解用户体验在游戏中的重要性。\n【加分项】\n1. 有游戏行业实习经验；\n2. 接受过游戏设计相关教育或培训；\n3. 对不同类型的游戏和平台（PC、移动、主机）有广泛的了解和热爱（简历请附上游戏经历：包括但不限于游戏类型、游戏名称、游戏平台、游戏时长、游戏成就，喜欢这款游戏的原因等）；\n4. 因热爱画画拥有不俗的审美，因喜爱文字擅长编辑语言，有一技之长；\n5. 具备第二语言的技能。\n\n我们正在寻找富有灵气的游戏交互实习生，他们热衷创作、充满想象，对游戏总是有无法遏制的灵感与激情，对将各类玩家带进游","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903720037","sourceKey":"alibaba","company":"阿里巴巴","title":"投资实习生","city":"北京/上海","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903720037?deptCodes=","duty":"加入我们能获得什么？\n我们是阿里国际集团投资部，业务覆盖全球，团队成员均来自全球顶尖投资公司，加入我们有机会接触和参与全球领先投资项目及各行业赛道，全方面接触投资业务的各个环节，实现高速成长。\n\n参与协助全球行业研究、海外投资机会分析、公司经营和财务数据分析、估值分析等工作。","requirements":"1. 在读大三及以上年级同学，大四/研一/研二/MBA优先；\n2. 有较强的行业研究、估值模型搭建、财务分析能力优先；\n3. 具有极强的自驱力、学习能力和抗压能力；\n4. 具有契约精神，对于公司相关的项目和交易严格保密；\n5. 英文流利，有投资、投行或咨询类实习经历优先；\n6. 每周5个工作日至少出席3天及以上、连续实习不少于3个月。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903740003","sourceKey":"alibaba","company":"阿里巴巴","title":"Content operation -Overseas Market（Intern）","city":"纽约市","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903740003?deptCodes=","duty":"1. Availability ≥4 days/week, internship duration ≥3 months.\n2. Overseas education (QS100), corporate internship, or successful self-media operation experience.\n3. Proficient in video editing, graphic design tools; familiarity with AI tools is a plus.\n4. Fluent in English (working proficiency).","requirements":"1. Assist in trend analysis and user insights on overseas social media platforms (Instagram, Facebook, LinkedIn, YouTube). Create content to enhance content quality and engagement rates, boosting Alibaba.com’s visibility in target markets.\n2. Engage with overseas communities/KOLs/KOCs to amplify brand influence.\n3. Support content creation and execution for large campaigns.\n4. Collaborate across t","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903740005","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生-通算智算一体化性能分析诊断方法与深度优化","city":"北京/杭州/上海","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903740005?deptCodes=","duty":"1、探索通算智算一体化场景下，端到端性能分析诊断体系的研究与构建，覆盖从底层硬件（CPU、GPU、NPU等）、系统软件到上层分布式框架和应用负载；\n2、深入研究CPU-GPU异构计算系统、分布式框架、系统软件栈（如操作系统、编译器、运行时）的性能瓶颈，提出并实现创新的软硬件协同优化方案；\n3、开发和落地先进的性能监控、剖析和诊断工具，支持从底层硬件指标到上层业务负载的全链路追踪与精准瓶颈定位；\n4、针对大规模AI模型训练/推理、通用计算等多样化负载，探索和实践GPU等异构资源的调度优化、资源容错、任务状态保存/恢复与快速迁移等关键技术，提升资源利用率和系统稳定性；\n5、研究内存（包括CPU内存和GPU显存）与计算的协同优化方案，旨在提升训推场景性能，降低整体成本，并优化资源利用率；\n6、将研究成果应用于阿里云平台及相关产品服务，提升云平台的整体性能、资源利用率和性价比，支持关键业务场景；\n","requirements":"1、扎实的计算机科学与工程功底，优秀的编程能力（精通或熟练掌握C/C++/Python等），熟悉常用数据结构、算法和设计模式，具备复杂系统设计、开发与调试经验。\n2、优秀的沟通表达、团队协作能力；具备快速学习新知识和深入钻研复杂技术问题的能力与耐心。\n3、深入理解计算机体系结构（CPU/GPU/NPU等）、操作系统、编译原理、分布式系统等基础知识。\n4、具备以下至少一个领域的深入实践经验：\n  1）高性能计算（HPC），特别是异构计算环境下的性能分析与优化；\n  2）GPU编程与优化（如CUDA, ROCm, OpenCL等），熟悉GPU架构；\n  3）系统性能分析与调优工具（如perf, eBPF, VTune, Nsight Profiler等）的开发或深度使用经验；\n  4）虚拟化（KVM/QEMU等）、容器技术（Docker/Kubernetes等）及其性能优化；\n  5）分布式系","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903740007","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 云原生向量数据库核心架构优化","city":"杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903740007?deptCodes=","duty":"1.研发新一代向量数据压缩存储格式；\n2.设计基于JIT的索引快速预热机制；\n3.优化磁盘-内存-GPU数据传输流水线；\n4.开发分布式一致性内存管理组件。","requirements":"1.计算机科学博士/硕士在读，在数据库、人工智能、系统等领域有顶会论文发表经验优先；\n2.精通C/C++与CUDA编程，熟悉LSM-tree等存储结构；\n3.有FPGA/GPU加速开发经验者优先；\n4.熟悉分布式一致性协议与RDMA编程。","description":"","jdComplete":false,"sourceStatus":null},{"id":"alibaba:199903740009","sourceKey":"alibaba","company":"阿里巴巴","title":"研究型实习生 - 面向公有云的大规模资源调度算法优化技术研究","city":"北京/杭州","category":"","channels":[],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus-talent.alibaba.com/campus/position/199903740009?deptCodes=","duty":"我们致力于优化云计算场景下的弹性计算服务（ECS）资源调度系统，通过算法创新解决动态资源分配、集群资源优化等核心问题。本岗位将深度参与资源调度算法的设计与实现，推动资源装箱效率提升、性能争用降低等关键技术突破，最终实现资源供给成本优化与整体资源利用率的显著提升。具体职责包括：\n1. 研究并设计面向云计算场景的资源调度算法，解决海量算力需求下的资源分配效率问题；\n2. 结合服务等级协议（SLA）要求，优化调度系统在成本、稳定性、性能等多目标约束下的决策机制；\n3. 分析集群资源使用数据，建设资源画像，提出并实施资源利用率提升方案；\n4. 实现算法原型，推动算法在实际生产环境中的落地与迭代；\n5. 跟踪前沿技术动态，探索机器学习、强化学习等技术在资源调度领域的创新应用。","requirements":"1. 计算机科学、人工智能、运筹学、数学等相关专业本科及以上学历\n2. 扎实的工程能力，优良的编程风格，熟悉Python/C++语言和常用设计模式，具备复杂系统的设计开发调试能力\n3. 具备扎实的算法基础，熟悉优化算法及调度理论\n4. 具备良好的英文技术文档阅读和撰写能力。\n\n加分项：\n1. 有突出的学术背景和创新研究能力，在顶会顶刊发表过相关论文\n2. 对云计算平台或开源调度系统有研究实践经验","description":"","jdComplete":false,"sourceStatus":null}];
